# Let's construct a complete 4-partite graph with partition sizes 3, 3, 3, 2
# This will have chromatic number 4, max clique size 4, and we need to check min degree

parts = [
    [0, 1, 2],      # Part 1: size 3
    [3, 4, 5],      # Part 2: size 3
    [6, 7, 8],      # Part 3: size 3
    [9, 10]         # Part 4: size 2
]

edges = []
for i in range(len(parts)):
    for j in range(i+1, len(parts)):
        for u in parts[i]:
            for v in parts[j]:
                edges.append((min(u,v), max(u,v)))

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Check degrees
from collections import Counter
degree = Counter()
for u, v in edges:
    degree[u] += 1
    degree[v] += 1

print(f"Degrees: {dict(degree)}")
print(f"Minimum degree: {min(degree.values())}")

# Check max clique size using brute force
from itertools import combinations

def is_clique(vertices, edge_set):
    for u, v in combinations(vertices, 2):
        if (min(u,v), max(u,v)) not in edge_set:
            return False
    return True

edge_set = set(edges)
max_clique = 0
for size in range(1, 12):
    found = False
    for subset in combinations(range(11), size):
        if is_clique(subset, edge_set):
            found = True
            break
    if found:
        max_clique = size
    else:
        break

print(f"Maximum clique size: {max_clique}")

# Check chromatic number (should be 4 for complete 4-partite)
print(f"Chromatic number: 4 (complete 4-partite graph)")
